<?php require_once 'config/helpers.php'; $count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();$message='';if($count>0){$message='An administrator already exists. Delete setup_admin.php from your project for security.';}elseif($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12){$message='Enter a name, valid email and password of at least 12 characters.';}else{$st=$pdo->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$st->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$message='Admin account created. Now delete setup_admin.php and login as Administrator.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Admin setup</title></head><body><main class="container"><div class="form-wrap panel"><h1 class="section-title">Create First Admin</h1><?php if($message): ?><div class="alert"><?= e($message) ?></div><?php endif; ?><?php if($count===0): ?><form method="post" class="form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div><label>Admin name</label><input name="name" required></div><div><label>Admin email</label><input type="email" name="email" required></div><div><label>Password (12+ characters)</label><input type="password" name="password" minlength="12" required></div><button>Create Admin Account</button></form><?php endif; ?><p><a href="login.php">Go to login</a></p></div></main></body></html>
